414:export async function hold(page: Page, personId: string, f: { from?: string; to?: string }): Promise<boolean> {
777:export async function pasteClaims(page: Page, text: string): Promise<number | null> {
940:export async function claimAction(page: Page, claimId: string, action: string, reason?: string): Promise<boolean> {
1002:export async function holdClaim(page: Page, claimId: string): Promise<boolean> {
1098:export async function bulkOpen(page: Page, claimIds: string[]): Promise<{ opened: number; refused: number }> {
