# Change a person's name and grade. Validate before Load so an invalid body is a 400, not a 404.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.person.RecordPersonEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;


public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.find(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;


public class SavePerson {
    public void save(@Val Person person, People people) throws PersonConflictException {
        // Saved over by someone else between this request's load and its save: refused as a conflict.
        if (!people.save(person)) {
            Person current = people.find(person.getSheetId(), person.getId());
            throw new PersonConflictException(PersonResponse.from(current != null ? current : person));
        }
    }
}

